// T1.4 / T2.3 - read the six bins once per tick from the inject node.
// Each bin is its own Modbus unit ID with the same register map (docs/register_map.md):
//   0-1 gross weight in mg (uint32, high word first), 2 status, 3-4 simulated minutes, 5 cycle
const client = context.get('client');
const bins = global.get('bins').bins;
const host = env.get('MODBUS_HOST') || 'simulator';
const port = Number(env.get('MODBUS_PORT') || 5020);

if (context.get('busy')) return null;           // previous poll still running: skip this tick
context.set('busy', true);
try {
    if (!client.isOpen) {
        node.status({ fill: 'yellow', shape: 'ring', text: `connecting ${host}:${port}` });
        await client.connectTCP(host, { port });
    }
    const ts = new Date().toISOString();         // edge timestamp, used all the way to the database
    let ok = 0;
    for (const b of bins) {
        client.setID(b.unit_id);
        try {
            const r = (await client.readHoldingRegisters(0, 6)).data;
            node.send({
                topic: b.bin,
                payload: {
                    ts, bin_id: b.bin,
                    mg: r[0] * 65536 + r[1],         // decode the 32-bit weight
                    status: r[2],
                    sim_min: r[3] * 65536 + r[4],
                    cycle: r[5],
                },
            });
            ok += 1;
        } catch (err) {
            node.warn(`${b.bin} (unit ${b.unit_id}): ${err.message}`);
        }
    }
    node.status(ok === bins.length
        ? { fill: 'green', shape: 'dot', text: `${ok} bins read at ${ts.slice(11, 19)}` }
        : { fill: 'red', shape: 'ring', text: `only ${ok} of ${bins.length} bins read at ${ts.slice(11, 19)}` });
} catch (err) {
    node.status({ fill: 'red', shape: 'ring', text: `simulator unreachable: ${err.message}` });
    try { client.close(() => {}); } catch (e) { /* already closed */ }
} finally {
    context.set('busy', false);
}
return null;

