// T1.4 - one Modbus TCP client for all six bins (modbus-serial, loaded in settings.js)
const ModbusRTU = global.get('ModbusRTU');
const client = new ModbusRTU();
client.setTimeout(500);
context.set('client', client);
context.set('busy', false);

