// T2.4 grams -> units, deadband and heartbeat; T3.2 fault flags.
// Output 1: level message to publish (only when it changed enough, or for the heartbeat)
// Output 2: every reading, to the P-240 node
const cfg = global.get('bins');
const p = msg.payload;
const bin = cfg.bins.find(b => b.bin === p.bin_id);
if (!bin) return null;
const e = cfg.edge;
const st = context.get(bin.bin) || { lastMg: null, sameSince: p.sim_min, samePolls: 0,
                                     pubUnits: null, pubStatus: null, pubAt: 0, cycle: p.cycle };

// Units on the scale, then back to facility units with the scale factor k.
// Math.round instead of floor: a small negative noise would otherwise drop a whole unit.
const grams = p.mg / 1000;
const units = Math.max(0, Math.round((grams - bin.tare_g) / bin.unit_g)) * bin.scale_k;

// T3.2 - stuck sensor: real load cells always show some noise, so the same raw value
// for many polls, while the average demand says units should have gone, means stuck.
if (p.cycle !== st.cycle) {                        // replay restarted: start over
    st.cycle = p.cycle; st.lastMg = null; st.samePolls = 0;
}
if (p.mg === st.lastMg) {
    st.samePolls += 1;
} else {
    st.lastMg = p.mg; st.samePolls = 0; st.sameSince = p.sim_min;
}
const expectedGone = bin.d_day * (p.sim_min - st.sameSince) / 1440;
const stuck = st.samePolls >= e.stuck_polls && expectedGone >= e.stuck_min_expected_units;

// status: 0 OK, 1 fault reported by the sensor (register 40003), 2 stuck (detected here)
let status = 0, flag = 'ok';
if (p.status === 1) { status = 1; flag = 'hard_fault'; }
else if (stuck) { status = 2; flag = 'stuck'; }

// Deadband: publish only if units moved by at least deadband_units or the status changed;
// heartbeat: publish anyway every heartbeat_s so the dashboard sees the bin is alive.
const now = Date.now();
const changed = st.pubUnits === null || Math.abs(units - st.pubUnits) >= bin.deadband_units
                || status !== st.pubStatus;
const heartbeat = !changed && now - st.pubAt >= e.heartbeat_s * 1000;
let level = null;
if (changed || heartbeat) {
    st.pubUnits = units; st.pubStatus = status; st.pubAt = now;
    level = {
        topic: `css/${cfg.ue}/bins/${bin.bin}/level`, qos: 1, retain: true,
        payload: { ts: p.ts, bin_id: bin.bin, item: bin.item, units,
                   grams: Math.round(grams * 10) / 10, status, flag, rop: bin.ROP,
                   sim_min: p.sim_min, cycle: p.cycle, heartbeat },
    };
}
context.set(bin.bin, st);
node.status({ fill: status ? 'red' : 'green', shape: 'dot', text: `${bin.bin}: ${units} units ${flag}` });
return [level, { topic: bin.bin, payload: { ts: p.ts, bin_id: bin.bin, units, status,
                                            sim_min: p.sim_min, cycle: p.cycle } }];

// T2.6 - P-240 reorder rule at the edge (edge/lib/p240.js), with hysteresis.
// Output 1: reorder event, css/{ue}/bins/{bin}/reorder (QoS 1, not retained)
// Output 2: the same event as a GS1 EPCIS 2.0 ObjectEvent (T3.7), css/{ue}/bins/{bin}/epcis
const cfg = global.get('bins');
const p240 = global.get('p240');
const epcis = global.get('epcis');
const r = msg.payload;
const bin = cfg.bins.find(b => b.bin === r.bin_id);
if (!bin) return null;

// T3.2 - a flagged bin (hard fault or stuck) never triggers a reorder: flag, don't order
if (r.status !== 0) {
    node.status({ fill: 'red', shape: 'ring', text: `${bin.bin} flagged: reorder suppressed` });
    return null;
}

const rop = p240.computeRop(bin, cfg.p240);
const res = p240.check(context.get(bin.bin), r.units, rop.rop, cfg.p240.rearm_margin);
context.set(bin.bin, res.state);
if (!res.fire) return null;

const ev = Object.assign(p240.reorderEvent(bin, r.units, rop, r.ts),
                         { sim_min: r.sim_min, cycle: r.cycle });
node.status({ fill: 'yellow', shape: 'dot', text: `REORDER ${bin.bin}: ${r.units} <= ${ev.rop}` });
return [
    { topic: `css/${cfg.ue}/bins/${bin.bin}/reorder`, qos: 1, retain: false, payload: ev },
    { topic: `css/${cfg.ue}/bins/${bin.bin}/epcis`, qos: 1, retain: false,
      payload: epcis.fromReorder(ev, cfg.ue) },
];

// T3.3 - store-and-forward. Messages pass straight through while the broker is connected.
// While it is down they wait in a queue in the 'file' context store (survives a restart),
// and on reconnect they are sent in order, before any new message.
// Two inputs: the messages to publish, and status updates of the mqtt out node (Status node).
// Node-RED's MQTT node silently drops a publish while it is disconnected, and its status
// arrives a moment after the link breaks; so the messages sent in the last RECENT_MS are
// kept and put back at the head of the queue when the broker goes down. A message that did
// arrive may then be sent twice: harmless, it lands on the same InfluxDB point (QoS 1 =
// at least once).
const QUEUE = 'queue', STORE = 'file', MAX_QUEUE = 50000, BATCH = 50, RECENT_MS = 5000;

function remember(m) {                              // keep what was sent in the last RECENT_MS
    const now = Date.now();
    const recent = (context.get('recent') || []).filter(r => now - r.t < RECENT_MS);
    recent.push({ t: now, m });
    context.set('recent', recent);
}

function show() {
    const n = (context.get(QUEUE, STORE) || []).length;
    if (context.get('up') === true && n === 0) node.status({ fill: 'green', shape: 'dot', text: 'broker connected' });
    else node.status({ fill: 'yellow', shape: 'ring', text: `${context.get('up') ? 'sending backlog' : 'broker down'}: ${n} queued` });
}

function flush() {
    if (context.get('flushing')) return;
    context.set('flushing', true);
    const step = () => {
        const q = context.get(QUEUE, STORE) || [];
        if (q.length === 0 || context.get('up') !== true) {
            context.set('flushing', false); show(); return;
        }
        const batch = q.splice(0, BATCH);
        context.set(QUEUE, q, STORE);
        batch.forEach(m => { remember(m); node.send(m); });
        show();
        setTimeout(step, 100);
    };
    step();
}

if (msg.status) {                                   // from the Status node
    const up = msg.status.fill === 'green';
    const wasUp = context.get('up') === true;
    context.set('up', up);
    if (!up && wasUp) {                             // link just dropped: re-queue the last few seconds
        const recent = (context.get('recent') || []).map(r => r.m);
        context.set('recent', []);
        context.set(QUEUE, recent.concat(context.get(QUEUE, STORE) || []), STORE);
    }
    if (up && !wasUp) flush();
    show();
    return null;
}

const q = context.get(QUEUE, STORE) || [];
const m = { topic: msg.topic, payload: msg.payload, qos: msg.qos, retain: msg.retain };
if (context.get('up') === true && q.length === 0 && !context.get('flushing')) {
    remember(m);
    return m;
}
q.push(m);
if (q.length > MAX_QUEUE) q.shift();               // keep the newest if the outage is very long
context.set(QUEUE, q, STORE);
show();
return null;

initialize:
// After a deploy or restart: not connected until the Status node says so, no flush running.
// (The queue itself is kept in the 'file' store and is sent once the broker is connected.)
context.set('up', false);
context.set('flushing', false);
context.set('recent', []);
